// Valida a entrada e aplica limite de uso. Mantenha LIMITES e REGEX_EMAIL iguais aos de js/utils.js.

const LIMITES = { nome: 100, email: 254, assunto: 150, mensagemMin: 10, mensagemMax: 2000 };
const REGEX_EMAIL = /^[^\s@]+@[^\s@.]+(?:\.[^\s@.]+)*\.[^\s@.]{2,}$/;

// Limites: por IP (1 min) e global (1 h).
const JANELA_MS = 60 * 1000;
const MAX_POR_JANELA = 10;
const MAX_GLOBAL_POR_HORA = 300;
const MAX_IPS_RASTREADOS = 1000;

function limparTexto(valor, multilinha) {
  if (typeof valor !== 'string') return null;
  let texto = valor
    .replace(/\r\n?/g, '\n')
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '');
  if (!multilinha) texto = texto.replace(/\s+/g, ' ');
  return texto.trim();
}

function recusar(status, codigo, erro, detalhes) {
  const resposta = { sucesso: false, codigo, erro };
  if (detalhes) resposta.detalhes = detalhes;
  return [{ json: { valido: false, status, resposta } }];
}

const entrada = $input.first().json;
const corpo =
  entrada.body && typeof entrada.body === 'object' && !Array.isArray(entrada.body) ? entrada.body : {};
const cabecalhos = entrada.headers || {};

// Validação
const nome = limparTexto(corpo.nome, false);
const email = limparTexto(corpo.email, false);
const assunto = limparTexto(corpo.assunto, false);
const mensagem = limparTexto(corpo.mensagem, true);
const erros = [];

if (!nome) erros.push('Informe o nome do contato.');
else if (nome.length > LIMITES.nome) erros.push(`O nome deve ter no máximo ${LIMITES.nome} caracteres.`);

if (!email) erros.push('Informe o e-mail.');
else if (email.length > LIMITES.email || !REGEX_EMAIL.test(email)) erros.push('Informe um e-mail válido.');

if (!assunto) erros.push('Informe o assunto.');
else if (assunto.length > LIMITES.assunto) erros.push(`O assunto deve ter no máximo ${LIMITES.assunto} caracteres.`);

if (!mensagem) erros.push('Escreva a mensagem.');
else if (mensagem.length < LIMITES.mensagemMin) erros.push(`A mensagem deve ter pelo menos ${LIMITES.mensagemMin} caracteres.`);
else if (mensagem.length > LIMITES.mensagemMax) erros.push(`A mensagem deve ter no máximo ${LIMITES.mensagemMax} caracteres.`);

if (erros.length > 0) {
  return recusar(400, 'VALIDACAO', 'Dados inválidos: ' + erros.join(' '), erros);
}

// Limite de uso (só pedidos válidos)
// Estado em static data: só persiste em execuções de produção.
const dados = $getWorkflowStaticData('global');
const agora = Date.now();
if (!dados.limite) dados.limite = { porIp: {}, hora: { inicio: agora, total: 0 } };
const limite = dados.limite;

for (const [chave, marcas] of Object.entries(limite.porIp)) {
  const recentes = marcas.filter((t) => agora - t < JANELA_MS);
  if (recentes.length > 0) limite.porIp[chave] = recentes;
  else delete limite.porIp[chave];
}
if (Object.keys(limite.porIp).length > MAX_IPS_RASTREADOS) limite.porIp = {};
if (agora - limite.hora.inicio >= 60 * 60 * 1000) limite.hora = { inicio: agora, total: 0 };

// O IP vem de cabeçalho forjável; o teto global protege a cota da API.
const encaminhado = String(cabecalhos['x-forwarded-for'] || '').split(',')[0].trim();
const ip = encaminhado || String(cabecalhos['x-real-ip'] || '').trim() || 'desconhecido';

const marcasDoIp = limite.porIp[ip] || [];
if (marcasDoIp.length >= MAX_POR_JANELA) {
  return recusar(429, 'LIMITE_EXCEDIDO', 'Muitas solicitações em pouco tempo. Aguarde um minuto e tente novamente.');
}
if (limite.hora.total >= MAX_GLOBAL_POR_HORA) {
  return recusar(429, 'LIMITE_EXCEDIDO', 'O limite de análises por hora foi atingido. Tente novamente mais tarde.');
}
marcasDoIp.push(agora);
limite.porIp[ip] = marcasDoIp;
limite.hora.total += 1;

// Entrada validada
return [{ json: { valido: true, contato: { nome, email, assunto, mensagem } } }];

