// Valida a resposta do Gemini e monta o JSON final. Mantenha CATEGORIAS e PRIORIDADES iguais às de js/utils.js.

const CATEGORIAS = ['Dúvida', 'Orçamento', 'Suporte', 'Outro'];
const PRIORIDADES = ['Baixa', 'Média', 'Alta'];
const MAX_RESUMO = 400;
const MAX_RESPOSTA = 1200;

function falha(status, codigo, erro) {
  return [{ json: { ok: false, status, resposta: { sucesso: false, codigo, erro } } }];
}

function chave(texto) {
  return String(texto == null ? '' : texto)
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .trim()
    .toLowerCase();
}

function normalizar(valor, permitidos) {
  return permitidos.find((p) => chave(p) === chave(valor)) || null;
}

function cortar(texto, max) {
  const limpo = texto.trim();
  return limpo.length > max ? limpo.slice(0, max - 1).trimEnd() + '…' : limpo;
}

const item = $input.first().json || {};

// Falha na chamada HTTP (detalhes ficam só no histórico do n8n).
if (item.error) {
  return falha(502, 'IA_INDISPONIVEL', 'O serviço de IA está indisponível no momento. Tente novamente em alguns instantes.');
}

// Prompt bloqueado pelo modelo.
if (item.promptFeedback && item.promptFeedback.blockReason) {
  return falha(422, 'IA_BLOQUEADA', 'O serviço de IA não pôde analisar esta mensagem. Reescreva o texto e tente novamente.');
}

// Extrai o texto.
const candidato = Array.isArray(item.candidates) ? item.candidates[0] : null;
const partes = candidato && candidato.content && Array.isArray(candidato.content.parts) ? candidato.content.parts : [];
const textoBruto = partes
  .filter((p) => p && typeof p.text === 'string' && !p.thought)
  .map((p) => p.text)
  .join('')
  .trim();

if (!textoBruto) {
  if (candidato && candidato.finishReason === 'SAFETY') {
    return falha(422, 'IA_BLOQUEADA', 'O serviço de IA não pôde analisar esta mensagem. Reescreva o texto e tente novamente.');
  }
  return falha(502, 'IA_RESPOSTA_INVALIDA', 'A IA não retornou uma resposta utilizável. Tente novamente.');
}

// Converte para objeto (tolera cerca ```json).
function converter(texto) {
  const semCerca = texto.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  try {
    return JSON.parse(semCerca);
  } catch (e) {
    const inicio = semCerca.indexOf('{');
    const fim = semCerca.lastIndexOf('}');
    if (inicio >= 0 && fim > inicio) {
      try {
        return JSON.parse(semCerca.slice(inicio, fim + 1));
      } catch (e2) {
        return null;
      }
    }
    return null;
  }
}

const objeto = converter(textoBruto);
const respostaInvalida = () =>
  falha(502, 'IA_RESPOSTA_INVALIDA', 'A IA retornou uma resposta em formato inesperado. Tente novamente.');

if (!objeto || typeof objeto !== 'object' || Array.isArray(objeto)) return respostaInvalida();

// Valida cada campo.
const categoria = normalizar(objeto.categoria, CATEGORIAS);
const prioridade = normalizar(objeto.prioridade, PRIORIDADES);
const resumo = typeof objeto.resumo === 'string' ? objeto.resumo.trim() : '';
const respostaSugerida = typeof objeto.resposta_sugerida === 'string' ? objeto.resposta_sugerida.trim() : '';

if (!categoria || !prioridade || !resumo || !respostaSugerida) return respostaInvalida();

return [
  {
    json: {
      ok: true,
      status: 200,
      resposta: {
        sucesso: true,
        dados: {
          categoria,
          resumo: cortar(resumo, MAX_RESUMO),
          prioridade,
          resposta_sugerida: cortar(respostaSugerida, MAX_RESPOSTA),
        },
      },
    },
  },
];
